{
  "kind": "meal planner",
  "asked": [
    "plan weekly dinners",
    "save recipes from websites",
    "make a grocery list sorted by aisle",
    "use up what is in the fridge"
  ],
  "also_needed": [
    "consider dietary restrictions",
    "suggest healthy meal options"
  ],
  "jobs": [
    {
      "name": "meal planning",
      "does": "create a weekly dinner plan for a family of five",
      "parts": [
        { "kind": "code-app", "search": ["meal planner", "weekly meal plan"] },
        { "kind": "knowledge", "search": ["meal planning for families", "meal planning with dietaryrestrictions"] }
      ]
    },
    {
      "name": "recipe saving",
      "does": "store recipes from various websites",
      "parts": [
        { "kind": "code-app", "search": ["recipe saver", "recipe manager"] },
        { "kind": "data-template", "search": ["recipe database", "recipe spreadsheet"] }
      ]
    },
    {
      "name": "grocery list creation",
      "does": "generate a grocery list based on the meal plan",
      "parts": [
        { "kind": "code-app", "search": ["grocery list generator", "shopping list app"] },
        { "kind": "data-template", "search": ["grocery list template", "shopping list template"] }
      ]
    },
    {
      "name": "aisle sorting",
      "does": "organize the grocery list by store aisles",
      "parts": [
        { "kind": "code-app", "search": ["aisle sorting", "grocery list by aisle"] },
        { "kind": "knowledge", "search": ["grocery store layout", "store aisle organization"] }
      ]
    },
    {
      "name": "fridge inventory",
      "does": "use existing food in the fridge to suggest meals",
      "parts": [
        { "kind": "code-app", "search": ["fridge inventory", "use fridge inventory"] },
        { "kind": "live-info", "search": ["local grocery store prices", "grocery store inventory"] }
      ]
    },
    {
      "name": "dietary restriction handling",
