        { "kind": "code-app", "search": ["dietary restrictions", "gluten free recipes", "peanut allergy recipes"] },
        { "kind": "knowledge", "search": ["gluten free cooking", "peanut allergy cooking"] }
      ]
    },
    {
      "name": "healthy meal suggestions",
      "does": "provide nutritious meal options",
      "parts": [
        { "kind": "code-app", "search": ["healthy meal planner", "healthy meal suggestions"] },
        { "kind": "knowledge", "search": ["healthy eating", "balanced diet"] }
      ]
    }
  ]
}
